import pandas as pd
import numpy as np

def clean_value(val):
    if pd.isna(val):
        return np.nan
    if isinstance(val, str):
        val = val.replace('"', '').replace(',', '.')
        try:
            return float(val)
        except ValueError:
            return np.nan
    try:
        return float(val)
    except:
        return np.nan

# Load data
df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')

# Step 1: Handle format issues (commas, scientific notation)
# We do this column by column to keep patient_id
patient_ids = df['patient_id']
df_data = df.drop(columns=['patient_id'])

for col in df_data.columns:
    df_data[col] = df_data[col].apply(clean_value)

# Step 2: Remove patient rows with missing values
# Combine back with patient_id to drop rows consistently
df_combined = pd.concat([patient_ids, df_data], axis=1)
df_clean = df_combined.dropna().copy()

# Step 3: Unit harmonization
def harmonize(row):
    # Serum_Creatinine: mg/dL vs µmol/L (factor 88.4)
    if row['Serum_Creatinine'] > 30:
        row['Serum_Creatinine'] /= 88.4

    # Hemoglobin: g/dL vs g/L (factor 10)
    if row['Hemoglobin'] > 30:
        row['Hemoglobin'] /= 10

    # Albumin_Serum: g/dL vs g/L (factor 10)
    if row['Albumin_Serum'] > 10:
        row['Albumin_Serum'] /= 10

    # Total_Protein: g/dL vs g/L (factor 10)
    if row['Total_Protein'] > 15:
        row['Total_Protein'] /= 10

    # Total_Bilirubin: mg/dL vs µmol/L (factor 17.1)
    if row['Total_Bilirubin'] > 5:
        row['Total_Bilirubin'] /= 17.1

    # Direct_Bilirubin: mg/dL vs µmol/L (factor 17.1)
    if row['Direct_Bilirubin'] > 2:
        row['Direct_Bilirubin'] /= 17.1

    # Glucose: mg/dL vs mmol/L (factor 18.016)
    if row['Glucose'] < 25:
        row['Glucose'] *= 18.016

    # Total_Cholesterol: mg/dL vs mmol/L (factor 38.67)
    if row['Total_Cholesterol'] < 15:
        row['Total_Cholesterol'] *= 38.67

    # LDL_Cholesterol: mg/dL vs mmol/L (factor 38.67)
    if row['LDL_Cholesterol'] < 10:
        row['LDL_Cholesterol'] *= 38.67

    # HDL_Cholesterol: mg/dL vs mmol/L (factor 38.67)
    if row['HDL_Cholesterol'] < 5:
        row['HDL_Cholesterol'] *= 38.67

    # Triglycerides: mg/dL vs mmol/L (factor 88.57)
    if row['Triglycerides'] < 15:
        row['Triglycerides'] *= 88.57

    # Uric_Acid: mg/dL vs µmol/L (factor 59.48)
    if row['Uric_Acid'] > 20:
        row['Uric_Acid'] /= 59.48

    # Serum_Calcium: mg/dL vs mmol/L (factor 4.0)
    if row['Serum_Calcium'] < 6:
        row['Serum_Calcium'] *= 4.0

    # Ionized_Calcium: mg/dL vs mmol/L (factor 4.0)
    if row['Ionized_Calcium'] < 2.5:
        row['Ionized_Calcium'] *= 4.0

    # Magnesium: mg/dL vs mmol/L (factor 2.43)
    if row['Magnesium'] < 1.2:
        row['Magnesium'] *= 2.43

    # Phosphorus: mg/dL vs mmol/L (factor 3.1)
    if row['Phosphorus'] < 1.5:
        row['Phosphorus'] *= 3.1

    # Lactate: mmol/L vs mg/dL (factor 9.008)
    if row['Lactate'] > 20:
        row['Lactate'] /= 9.008

    # Free_T4: ng/dL vs pmol/L (factor 12.87)
    if row['Free_T4'] > 10:
        row['Free_T4'] /= 12.87

    # Free_T3: pg/mL vs pmol/L (factor 1.54)
    if row['Free_T3'] > 8:
        row['Free_T3'] /= 1.54

    # Troponin_I: ng/mL vs pg/mL (factor 1000)
    if row['Troponin_I'] > 10:
        row['Troponin_I'] /= 1000

    # Troponin_T: ng/mL vs pg/mL (factor 1000)
    if row['Troponin_T'] > 10:
        row['Troponin_T'] /= 1000

    # Urine_Creatinine: mg/dL vs µmol/L (factor 88.4)
    if row['Urine_Creatinine'] > 1000:
        row['Urine_Creatinine'] /= 88.4

    # Prealbumin: mg/dL vs mg/L?
    if row['Prealbumin'] > 100:
        row['Prealbumin'] /= 10

    return row

df_harmonized = df_clean.apply(harmonize, axis=1)

# Step 4: Round all values to 2 decimal places and format as X.XX
# patient_id should be integer but for CSV output we can just keep it or format it.
# The prompt says "numeric values should be 2 decimal places in such format: X.XX"

def format_float(val):
    return "{:.2f}".format(val)

# Apply formatting to all columns except patient_id
cols_to_format = [c for c in df_harmonized.columns if c != 'patient_id']
for col in cols_to_format:
    df_harmonized[col] = df_harmonized[col].apply(format_float)

# patient_id should be integer
df_harmonized['patient_id'] = df_harmonized['patient_id'].astype(int)

# Save to CSV
df_harmonized.to_csv('/root/ckd_lab_data_harmonized.csv', index=False)

